use rayon::prelude::*;

#[repr(C)]
#[derive(Clone, Copy, Debug)]
pub struct RgbaPixel {
    pub r: u8,
    pub g: u8,
    pub b: u8,
    pub a: u8,
}

/// Blends an active layer onto a background layer using 'Multiply' mode in parallel
pub fn blend_layers_multiply_parallel(base: &mut [RgbaPixel], overlay: &[RgbaPixel]) {
    assert_eq!(base.len(), overlay.len(), "Layer dimensions must match");

    // Parallel chunk processing across all available CPU hardware threads
    base.par_iter_mut()
        .zip(overlay.par_iter())
        .for_each(|(b, o)| {
            let alpha_factor = (o.a as f32) / 255.0;

            // Non-linear color blending formula (Multiply: A * B / 255)
            let mult_r = ((b.r as u32 * o.r as u32) / 255) as u8;
            let mult_g = ((b.g as u32 * o.g as u32) / 255) as u8;
            let mult_b = ((b.b as u32 * o.b as u32) / 255) as u8;

            // Alpha-composited final pixel values
            b.r = (b.r as f32 * (1.0 - alpha_factor) + mult_r as f32 * alpha_factor) as u8;
            b.g = (b.g as f32 * (1.0 - alpha_factor) + mult_g as f32 * alpha_factor) as u8;
            b.b = (b.b as f32 * (1.0 - alpha_factor) + mult_b as f32 * alpha_factor) as u8;
        });
}

use std::io::{self, Read, Cursor};
use byteorder::{BigEndian, ReadBytesExt};

#[derive(Debug, PartialEq)]
pub struct PsdHeader {
    pub version: u16,
    pub channels: u16,
    pub height: u32,
    pub width: u32,
    pub depth: u16,
    pub color_mode: u16,
}

pub fn parse_psd_header(bytes: &[u8]) -> Result<PsdHeader, io::Error> {
    let mut cursor = Cursor::new(bytes);

    // PSD signature must be exactly 4 bytes: '8BPS'
    let mut signature = [0u8; 4];
    cursor.read_exact(&mut signature)?;
    if &signature != b"8BPS" {
        return Err(io::Error::new(io::ErrorKind::InvalidData, "Not a valid Photoshop file"));
    }

    let version = cursor.read_u16::<BigEndian>()?;
    if version != 1 && version != 2 {
        return Err(io::Error::new(io::ErrorKind::InvalidData, "Unsupported PSD version"));
    }

    // 6 reserved bytes (must be zero)
    let mut reserved = [0u8; 6];
    cursor.read_exact(&mut reserved)?;

    let channels = cursor.read_u16::<BigEndian>()?;
    let height = cursor.read_u32::<BigEndian>()?;
    let width = cursor.read_u32::<BigEndian>()?;
    let depth = cursor.read_u16::<BigEndian>()?;
    let color_mode = cursor.read_u16::<BigEndian>()?;

    Ok(PsdHeader { version, channels, height, width, depth, color_mode })
}
